<?php

namespace Database\Seeders;

/** Seeds `services` from database/seeders/data/services.json (generated by scripts/export-seed-data.ts in the frontend repo). */
class ServicesSeeder extends ContentSeederBase
{
    public const TABLE = 'services';

    public function run(): void
    {
        if (! $this->tableReady(self::TABLE)) {
            return;
        }
        $images = ['hero_image' => 'services'];
        $keyCol = $this->hasColumn(self::TABLE, 'slug') ? 'slug' : 'name_ar';

        foreach ($this->json('services') as $row) {
            if (empty($row[$keyCol])) {
                continue;
            }
            $this->upsertFillEmpty(self::TABLE, [$keyCol => $row[$keyCol]], $row, $images);
        }

        $this->report(self::TABLE);
    }
}
